"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[9182],{3002(e){e.exports=JSON.parse('{"title":"\uc131\ub2a5 \ucd5c\uc801\ud654 \uccb4\ud06c\ub9ac\uc2a4\ud2b8","date":"2024-07-19","coverUrl":null,"html":"<h2 data-notion-block-id=\\"98e76aa9-cd98-4c55-9b45-2d4e46328d94\\" id=\\"98e76aa9-cd98-4c55-9b45-2d4e46328d94\\">\uc131\ub2a5 \ucd5c\uc801\ud654 \uccb4\ud06c\ub9ac\uc2a4\ud2b8</h2><a href=\\"https://www.speedcurve.com/blog/15-neglected-page-speed-optimizations/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.speedcurve.com/blog/15-neglected-page-speed-optimizations/</a><p data-notion-block-id=\\"b8cc99e1-3cc7-4e78-a76d-828de6b64e4b\\"><b>\uc2ec\uc724\uc12d</b>: \uc131\ub2a5 \ucd5c\uc801\ud654\ub77c\uace0 \ud574\uc11c \uc5b4\ub824\uc6b4 \ubd80\ubd84\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4. \uc5b4\ub5a8 \ub54c\ub294 \uc758\uc678\ub85c \uac04\ub2e8\ud558\uac8c \ud574\uacb0\ud560 \uc218\ub3c4 \uc788\uace0, \uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub294 \uba54\ubaa8\ub9ac \ub364\ud504\uae4c\uc9c0 \ub0b4\ub824\uac00\uc57c \ud558\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc2b5\ub2c8\ub2e4(ex. <a href=\\"https://ridicorp.com/story/ridi-markdown-improvements/\\">\ub9ac\ub514\uc758 \uac1d\uccb4 \ub2e4\ud615\uc131 \ubb38\uc81c</a>). \uadf8\ub798\uc11c \ube60\ub974\uac8c \ub9cc\ub4dc\ub294 \uacbd\uc6b0\uc5d0 \ub193\uce5c \uc131\ub2a5 \uc774\uc288\ub97c \uc131\uc7a5\ud55c \ub2e4\uc74c\uc5d0\ub3c4 \ubabb \uace0\uce58\ub294 \uacbd\uc6b0\ub3c4 \ub9ce\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uadf8\ub798\uc11c \ud55c\ubc88\uc5d0 \ud574\uacb0\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4, \uac04\ub2e8\ud558\uac8c \uc2dc\uc791\ud560 \ubc29\ubc95\uc744 \uc5b4\ub5bb\uac8c \uc81c\uc548\ud574\uc57c \ud560\uc9c0 \uace0\ubbfc\ud574\uc57c\uaca0\ub124\uc694. \uc124\ub4dd\ub3c4 \ud558\ub098\uc758 \uc77c\uc774\ub2c8\uae4c\uc694(\ud56d\uc0c1 <a href=\\"https://engineering.linecorp.com/ko/blog/about-demaecan-recode-project\\">\ub77c\uc778\uc758 \ub9ac\ucf54\ub4dc</a> \uae00\uc774 \ucc38\uace0\uac00 \ub41c\ub2e4\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4).</p><p data-notion-block-id=\\"f0290a6d-4442-4414-8826-267f406a9343\\">\uae40\ub300\uad00: \uc6f9 \uc131\ub2a5 \ucd5c\uc801\ud654\ub294 \ubaa8\ub4e0 \ud504\ub860\ud2b8 \uc5d4\uc9c0\ub2c8\uc5b4\ub77c\uba74 \uace0\ubbfc\ud574\ubd10\uc57c\ud558\ub294 \ubb38\uc81c\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc704 \uae00\uc5d0\uc11c \ub098\uc640\uc788\ub294 \ubb38\uc81c \uc911 \ud574\uacb0\ud574\ubcf8 \uac83\ub3c4 \uc788\uace0, \ud574\uacb0\ud558\uc9c0 \ubabb\ud55c \uac83\ub3c4 \uc788\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc704\uc640 \uac19\uc740 \ubb38\uc81c\ub4e4\uc744 \ud574\uacb0\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc6f9\uc5d0\uc11c\ub9cc \ud574\uacb0\ud560 \uc218 \uc788\ub294 \ubb38\uc81c\ub3c4 \uc788\uace0, \uc11c\ubc84 \uac1c\ubc1c\uc790\uc640 \ud611\uc5c5\uc744 \ud1b5\ud574 \ucd5c\uc801\ud654\uac00 \ud544\uc694\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc6f9 \uc131\ub2a5 \ucd5c\uc801\ud654\ub97c \uc704\ud55c \ub2e4\uc591\ud55c \ubc29\ubc95\uc774 \uc788\uc74c\uc744 \uc0dd\uac01\ud558\uace0 \uc790\uc2e0\uc758 \uc6f9 \ud2b9\uc131\uc774 CSR\uc778\uc9c0? SSR\uc778\uc9c0? \ubd80\ud130 \uc2dc\uc791\ud574\uc11c \uc6f9\uc5d0\uc11c \ub80c\ub354\ub9c1\uc744 \ubc1c\uc0dd\uc2dc\ud0a4\ub294, \ube4c\ub4dc\uc640 \ubc30\ud3ec\uac00 \ub418\ub294 \uacfc\uc815\uc774 \uc5b4\ub5bb\uac8c \ub418\uc5b4 \uc788\ub294\uc9c0\ub97c \ubd84\uc11d\ud574\uc11c \uc131\ub2a5 \ucd5c\uc801\ud654\ub97c \uc9c4\ud589\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"56aff8d6-d406-4c21-a42d-1d24d28934f0\\" id=\\"56aff8d6-d406-4c21-a42d-1d24d28934f0\\">Tanstack query\uac00 React Suspense\ub97c \uc704\ud574 \uad6c\ud604\ud55c \ubc29\ubc95</h2><a href=\\"https://www.bbss.dev/posts/react-learn-suspense/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.bbss.dev/posts/react-learn-suspense/</a><p data-notion-block-id=\\"dca1d238-938f-4754-8539-a7fe9e2f207e\\"><b>\uc2ec\uc724\uc12d</b>: Tanstack query\ub97c \ucc98\uc74c\ubd80\ud130 \ub9cc\ub4e4\uc5b4\ubcf4\uba74\uc11c <code>Suspense</code>\uc640 <code>ErrorBoundary</code>\ub97c \ud65c\uc6a9\ud558\uae30 \uc704\ud574, \uadf8\ub9ac\uace0 \uc694\uccad \uc218\ub97c \uc904\uc774\uae30 \uc704\ud574 \uacf5\uc720 \uce90\uc2dc(SWR \uc5c6\uc774)\ub97c \uad6c\ucd95\ud558\ub294 \uacfc\uc815\uae4c\uc9c0 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Tanstack query\uac00 \uc5b4\ub5a4 \uc774\uc720\uc5d0 \uc758\ud574\uc11c \uc9c0\uae08\uacfc \uac19\uc740 \ud615\ud0dc\ub85c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \ubcfc \uc218 \uc788\uace0, \ub9cc\uc57d \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c Suspense\ub97c \uc0ac\uc6a9\ud574\uc57c \ud560 \uacbd\uc6b0 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud574\uc57c \ud560\uc9c0 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4. Susepnse\uac00 \ub0b4\ubd80\uc5d0\uc11c \ub3d9\uc791\ud558\ub294\uc9c0\ub97c \uc790\uc138\ud788 \uc54c\uae30 \uc704\ud574\uc11c\ub294 <a href=\\"https://jser.dev/react/2022/04/02/suspense-in-concurrent-mode-1-reconciling/\\">Suspense\ub294 \ub0b4\ubd80\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub098\uc694?</a>\ub97c \uc0b4\ud3b4\ubcf4\uba74 \ub354 \uc88b\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"27c5987d-801c-4011-a67a-8a6b21ec90bf\\">\uae40\ub300\uad00: <code>Suspense</code>\uc640 <code>ErrorBoundary</code>\ub97c \ud65c\uc6a9\ud558\uae30 \uc704\ud55c \uacfc\uc815\uc5d0\uc11c \uc0ac\uc6a9\ub418\ub294 fetch\uc640 Promise \ub3d9\uc791\ub4e4\uc744 \uc720\uc2ec\ud558\uac8c \ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uac1c\uc778\uc801\uc73c\ub85c <code>FetchCache</code> Class \ucf54\ub4dc\ubd80\ubd84\uc5d0\uc11c\uc758 Promise \uc0c1\ud0dc \ud578\ub4e4\ub9c1\uc744 hook\uacfc \uc5f0\uacb0 \uc9d3\ub294 \ubd80\ubd84\uc774 \uc544\uc8fc \uc778\uc0c1\uc801\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \ud639\uc2dc\ub098 Promise\uc640 \uce5c\uc219\ud558\uc9c0 \uc54a\ub2e4\uba74 <a href=\\"https://www.freecodecamp.org/news/guide-to-javascript-promises/\\">Promise \ub3d9\uc791 \uad00\ub828 \uc790\ub8cc</a>\ub97c \ucc38\uace0\ud558\uc2dc\uba74 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"60fbe951-3572-497a-b89f-f6042f2ffd7b\\" id=\\"60fbe951-3572-497a-b89f-f6042f2ffd7b\\">\uc560\ub2c8\uba54\uc774\uc158\uc5d0 <code>clip-path()</code>\ucca8\uac00\ud558\uae30</h2><a href=\\"https://emilkowal.ski/ui/the-magic-of-clip-path\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://emilkowal.ski/ui/the-magic-of-clip-path</a><p data-notion-block-id=\\"74f761a1-c3db-40ad-977a-d0d78100347c\\"><b>\uc2ec\uc724\uc12d</b>: <code>cilp-path()</code>\ub294 CSS\ub85c \ub3c4\ud615\uc744 \ub9cc\ub4dc\ub294 \uacbd\uc6b0\uac00 \uc544\ub2c8\ub77c\uba74 \ub9ce\uc774 \ubabb \ubd24\uc744 \uc18d\uc131\uc774\uc9c0\ub9cc, \ube44\uad50 \uc2ac\ub77c\uc774\ub354\ub098 \uc2a4\ud06c\ub864 \uc560\ub2c8\uba54\uc774\uc158, \ud0ed \uc804\ud658 \uc560\ub2c8\uba54\uc774\uc158\uc5d0\ub3c4 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uc27d\uace0 \uac04\ub2e8\ud55c \uc811\uadfc\ubc95\uc744 \uc81c\uc2dc\ud569\ub2c8\ub2e4. \uc560\ub2c8\uba54\uc774\uc158 \ub123\uc5b4\ub2ec\ub77c\ub294 \uc694\uccad\uc744 \uc704\ud574 \ud55c\ubc88 \ubcf4\uc2dc\uace0 \uc811\uadfc\ubc95\uc744 \ub098\uc911\uc5d0 \ucc3e\uc544\ubcf4\uae30 \uc704\ud574 \uc54c\uc544\ub450\ub294 \uac83\ub3c4 \ub098\uc058\uc9c0 \uc54a\uaca0\ub124\uc694!</p><h2 data-notion-block-id=\\"d9435453-a88c-4009-a297-4e09e04a4131\\" id=\\"d9435453-a88c-4009-a297-4e09e04a4131\\">Remix\uc758 route match\uc758 \uc0c8\ub85c\uc6b4 \uc811\uadfc</h2><a href=\\"https://remix.run/blog/fog-of-war\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://remix.run/blog/fog-of-war</a><p data-notion-block-id=\\"79f25b58-6a28-4053-ae56-b55a6469b7f7\\"><b>\uc2ec\uc724\uc12d</b>: Remix\uc5d0\uc11c\ub294 \ucc98\uc74c \ub85c\ub4dc \uc2dc\uc5d0 \uacbd\ub85c\uc5d0 \ub300\ud55c manifest \ud30c\uc77c\uc744 \ubaa8\ub450 \ub85c\ub4dc\ud588\ub294\ub370, \uc774\uc81c Fog of War \uc544\ud0a4\ud14d\uccd0\ub97c \ub3c4\uc785\ud558\uac8c \ub418\uba74 \uc804\uccb4 \uacbd\ub85c\ub97c \ubcf4\ub0b4\uc9c0 \uc54a\uace0 \uacbd\ub85c\uc5d0 \ub530\ub77c \uad00\ub828\ub41c \uacbd\ub85c\ub9cc \uac00\uc838\uc624\ub294 \uacfc\uc815\uc744 \uac70\uce69\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 \uc811\uadfc\ubc95\uc778\ub9cc\ud07c \uc548\uc815\ub418\uace0 \uc798 \uc4f0\uc778\ub2e4\uba74 \ub2e4\ub978 \uba54\ud0c0 \ud504\ub808\uc784\uc6cc\ud06c\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ub07c\uce60 \uc218\ub3c4 \uc788\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"a6d19558-2033-4851-aa50-694ce1ac171b\\" id=\\"a6d19558-2033-4851-aa50-694ce1ac171b\\">Node.js\uc5d0\uc11c \uc774\ubca4\ud2b8 \ub8e8\ud504 \uc9c0\uc5f0</h2><a href=\\"https://trigger.dev/blog/event-loop-lag\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://trigger.dev/blog/event-loop-lag</a><p data-notion-block-id=\\"08a555cb-8a7f-4c5b-b457-1e39da77bc9c\\">Node.js\uc5d0\uc11c \uc774\ubca4\ud2b8 \ub8e8\ud504\uc5d0\uc11c block\uc744 \uac10\uc9c0\ud558\uace0 \ud574\uacb0\ud558\ub294 \uae00\uc774\uc9c0\ub9cc, \uc774\ubca4\ud2b8 \ub8e8\ud504 \uc9c0\uc5f0\uc740 \ubb34\uc5c7\uc778\uc9c0, \uadf8\ub9ac\uace0 \ubaa8\ub2c8\ud130\ub9c1\uacfc \ud574\uacb0(\uadf8\ub9ac\uace0 \uc11c\ubc84\ub9ac\uc2a4\uac00 \uc778\uae30\uc788\ub294 \uc774\uc720\uae4c\uc9c0) \uc81c\uc2dc\ud558\ub294 \uc88b\uc740 \uae00\uc785\ub2c8\ub2e4. \ub2e8\uc21c\ud788 \uba54\uc778 \uc2a4\ub808\ub4dc\ub97c block\ud558\ub294 \ucf54\ub4dc\ub97c \uc791\uc131\ud558\uc9c0 \uc54a\ub294 \ud574\uacb0\ucc45\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc, \uadf8\uc5d0 \ubabb\uc9c0\uc54a\uac8c \ubaa8\ub2c8\ud130\ub9c1\ub3c4 \uc911\uc694\ud558\ub2c8 \uae00\uc744 \ub530\ub77c\uac00\ubcf4\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"703984f3-218f-48f8-b7eb-225f44ec8728\\" id=\\"703984f3-218f-48f8-b7eb-225f44ec8728\\">React \ucef4\ud30c\uc77c\ub7ec\ub294 \uba54\ubaa8\ub9ac \ub204\uc218\ub97c \uc7a1\uc9c0 \ubabb\ud55c\ub2e4.</h2><a href=\\"https://schiener.io/2024-07-07/react-closures-compiler\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://schiener.io/2024-07-07/react-closures-compiler</a><p data-notion-block-id=\\"8f6eb0b2-2440-46db-bb6f-6956a06c4d59\\">\ub9ac\uc561\ud2b8 \ucef4\ud30c\uc77c\ub7ec\ub85c <a href=\\"https://ones-to-watch.ethansup.net/news/post/a5902c7d-ee33-4db6-aaea-ea4820a7562f#969cfc7b-5f89-42de-896d-eacff8b32799\\">React\uc5d0\uc11c\uc758 \uba54\ubaa8\ub9ac \ub204\uc218</a>\uc640 \uac19\uc740 \uc0c1\ud669\uc744 \uc7ac\ud604\ud574\ub3c4, \ud074\ub85c\uc800\uc758 \uba54\ubaa8\ub9ac \ub204\uc218\ub294 \ub9c9\uc744 \uc218 \uc5c6\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://www.developerway.com/posts/i-tried-react-compiler\\">\uc624\ub298 \ub9ac\uc561\ud2b8 \ucef4\ud30c\uc77c\ub7ec\ub97c \uc0ac\uc6a9\ud574 \ubd24\ub294\ub370, \uc5b4\ub560\uc744 \uac83 \uac19\ub098\uc694?</a> (<a href=\\"https://junghan92.medium.com/\uc624\ub298-\ub9ac\uc561\ud2b8-\ucef4\ud30c\uc77c\ub7ec\ub97c-\uc0ac\uc6a9\ud574-\ubd24\ub294\ub370-\uc5b4\ub560\uc744-\uac83-\uac19\ub098\uc694-ece57f076b02\\">\ud55c\uad6d\uc5b4 \ubc88\uc5ed</a>)\uc5d0\uc11c\uc640 \uac19\uc774, \uc544\uc9c1 \ucef4\ud30c\uc77c\ub7ec\uac00 \uac08 \uae38\uc774 \uba49\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"06b6504b-d4e4-4113-b95c-37753bfe780c\\" id=\\"06b6504b-d4e4-4113-b95c-37753bfe780c\\">\ub9ac\uc561\ud2b8\uc5d0\uc11c \ub85c\uc9c1\ubd84\ub9ac</h2><a href=\\"https://profy.dev/article/react-architecture-domain-logic\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://profy.dev/article/react-architecture-domain-logic</a><p data-notion-block-id=\\"0b1fbf87-4513-4fcf-af16-848192226439\\">\ud558\ub098\uc758 \uad00\uc810\uc73c\ub85c \uc0dd\uac01\ud560\ub9cc\ud55c \uae00\uc774\uc5ec\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. <code>\\"use server\\"</code>\ub514\ub809\ud2f0\ube0c\uac00 \uc0c8\ub85c \uc0dd\uae30\uba74\uc11c \ub85c\uc9c1\uc774 \ud63c\ud569\ub420 \uc218 \uc788\uace0, \uadf8 \uacfc\uc815\uc5d0\uc11c validate \uacfc\uc815\uc744 \ud558\ub098\uc758 \ud568\uc218\ub85c \ube7c\ub294 \uacfc\uc815\uc744 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 \uc5ec\ub7ec \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc811\uadfc\ud560 \uc218\ub3c4 \uc788\uc73c\ub2c8(validate \uacfc\uc815\uc744 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0 \uc704\uc784, validate \ubd80\ubd84\uacfc \uc11c\ube44\uc2a4 \ud638\ucd9c \ubd80\ubd84\uc744 \ub2e4\ub978 \ud568\uc218\ub85c \ubd84\ub9ac\u2026) \ud558\ub098\uc758 \uad00\uc810\uc73c\ub85c \uc0dd\uac01\ud574\ub3c4 \uad1c\ucc2e\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4!</p><p data-notion-block-id=\\"171f4735-3869-4a53-b3a0-e2e98297c887\\"></p>"}')}}]);